use xiom.io;

fn main() -> Int {
  let item: Option[Str] = Some("Magic Sword");

  if let Some(equipment) = item {
    io.println("Equipped: " + equipment.to_str());
  } else {
    io.println("No item equipped");
  }

  let item2: Option[Str] = None;
  if let Some(equipment) = item2 {
    io.println("Equipped: " + equipment.to_str());
  } else {
    io.println("No item equipped");
  }
  return 0;
}
